from webify import create_app, route, html, head, title, body, div, h1, p, input_, button, script

def get_game_result(choice):
    if choice == "left":
        return "You encounter a friendly goblin who gives you a map. The map shows a hidden treasure room! Congratulations! You found the treasure!"
    elif choice == "right":
        return "You fall into a pit and get eaten by a giant spider. Game Over!"
    else:
        return "Invalid choice. Game Over!"

def game_app():
    @route('/')
    def index():
        return html(
            head(title("Adventure Game!")),
